export interface ZonaHelek {
  /// Índice de la zona en helek.json (`zonas`).
  i: number
  tipo: 'tormenta' | 'peligro' | 'clan'
  nombre: string
  /// Tormenta: intensidad máxima (0 Ghurmek, refugio; 1 Sek'tar; 2 Rokthar; 3 Rok'ithek). Peligro: 1 bajo, 2 medio, 3 alto. Clan: 0.
  nivel: number
  /// Nombre del clan (solo tipo clan).
  clan: string | null
  /// false = propuesta sin canon (la decide Álvaro).
  canon: boolean
  nota: string
  /// Contorno en coordenadas del lienzo (800×600, 1 unidad ≈ 1 km), como el de las regiones.
  d: string
}

export interface RutaHelek {
  /// Índice de la ruta en helek.json (`rutas`).
  i: number
  grupo: 'roads' | 'trails' | 'searoutes'
  /// Longitud del trazo en km.
  km: number
  /// km × rodeo del terreno (null por mar: el canon no fija velocidad por mar).
  kmAPie: number | null
  horas: number | null
  jornadas: number | null
}

